MODULES = {'configuration': '"""Deployment-time bindings. No DEV/PRD catalog, workspace or recipient defaults."""\nimport copy,hashlib,json,re\n\ndef quoted(name):\n    assert isinstance(name,str) and all(re.fullmatch(r\'[A-Za-z_][A-Za-z0-9_]*\',s) for s in name.split(\'.\')),\'Use plain UC identifiers in configuration: \'+str(name)\n    return \'.\'.join(\'`\'+s+\'`\' for s in name.split(\'.\'))\ndef literal(value):return "\'"+str(value).replace("\'","\'\'")+"\'"\ndef signature(cfg):\n    keys=(\'environment\',\'deployment_id\',\'expected_workspace_id\',\'output_catalog\',\'output_schema\',\'scopes\',\'sensitivity_tag\',\'legacy_pii_tag\',\'source_classification_tag_keys\',\'native_tag_prefix\',\'taxonomy\')\n    return hashlib.sha256(json.dumps({k:cfg[k] for k in keys},sort_keys=True,separators=(\',\',\':\')).encode()).hexdigest()\ndef monitor_id(cfg):\n    identity=[cfg[k] for k in (\'deployment_id\',\'environment\',\'expected_workspace_id\',\'output_catalog\',\'output_schema\')]\n    return cfg[\'deployment_id\']+\'_\'+cfg[\'environment\'].lower()+\'_\'+hashlib.sha256(json.dumps(identity).encode()).hexdigest()[:12]\ndef state_table(cfg):return cfg[\'output_catalog\']+\'.\'+cfg[\'output_schema\']+\'.classification_monitor_journal\'\ndef validate(cfg,require_runtime=False):\n    c=copy.deepcopy(cfg)\n    c[\'environment\']=c[\'environment\'].upper()\n    c[\'expected_workspace_id\']=str(c.get(\'expected_workspace_id\',\'\'))\n    assert isinstance(c[\'notifications\'][\'emails\'],list) and isinstance(c[\'notifications\'][\'destination_ids\'],list)\n    c[\'notifications\'][\'emails\']=sorted(set(c[\'notifications\'][\'emails\']))\n    c[\'notifications\'][\'destination_ids\']=sorted(set(c[\'notifications\'][\'destination_ids\']))\n    assert re.fullmatch(r\'[A-Za-z0-9_-]+\',c[\'environment\'])\n    assert re.fullmatch(r\'[A-Za-z0-9_-]+\',c[\'deployment_id\'])\n    quoted(c[\'output_catalog\']);quoted(c[\'output_schema\'])\n    assert c[\'scopes\'] and len(c[\'scopes\'])<=50\n    seen=set()\n    for scope in c[\'scopes\']:\n        quoted(scope[\'catalog\']);assert scope[\'catalog\'] not in seen,\'Duplicate source catalog\';seen.add(scope[\'catalog\'])\n        assert len(scope[\'mapping_table\'].split(\'.\'))==3;quoted(scope[\'mapping_table\'])\n        if scope.get(\'collate_assignment_table\'):\n            assert len(scope[\'collate_assignment_table\'].split(\'.\'))==3;quoted(scope[\'collate_assignment_table\'])\n            assert scope.get(\'collate_service\'),\'Specify the expected Collate service for the source.\'\n        if scope[\'catalog\']==c[\'output_catalog\']:\n            scope[\'excluded_schemas\']=sorted(set(scope.get(\'excluded_schemas\',[]))|{c[\'output_schema\'],\'information_schema\'})\n        else:scope[\'excluded_schemas\']=sorted(set(scope.get(\'excluded_schemas\',[]))|{\'information_schema\'})\n    taxonomy=c[\'taxonomy\'];assert len(taxonomy)>=2\n    assert len({t[\'classification\'] for t in taxonomy})==len(taxonomy)\n    assert len({t[\'priority\'] for t in taxonomy})==len(taxonomy)\n    assert all(isinstance(t[\'priority\'],int) and t[\'priority\']>0 and t[\'pii_class\'] for t in taxonomy)\n    m=c[\'monitor\'];assert m[\'poll_minutes\'] in (15,30,60)\n    assert 0<=m[\'classification_grace_minutes\']<=1440\n    assert 1<=m[\'reminder_hours\']<=720\n    assert 1<=m[\'maximum_notifications_per_run\']<=5000\n    assert 1<=m[\'maximum_columns\']<=100000\n    assert 0<=m[\'maximum_inventory_drop_fraction\']<=0.5\n    assert 7<=m[\'retention_days\']<=365\n    assert 0<=m.get(\'daily_summary_hour_utc\',13)<=23\n    assert m[\'notification_mode\']==\'digest\',\'This framework sends digests, never one email per column.\'\n    assert 0<c[\'collate_freshness_days\']<=365\n    assert m[\'initial_backlog_notifications\'] is False,\'Initial backlog is summarized, never emitted as per-column alerts.\'\n    if require_runtime:\n        assert re.fullmatch(r\'\\d+\',str(c.get(\'expected_workspace_id\',\'\'))),\'Set this environment\\\'s workspace ID.\'\n        assert c.get(\'warehouse_id\') and c.get(\'existing_cluster_id\'),\'Set approved warehouse and existing Spark cluster IDs.\'\n        assert c[\'notifications\'][\'emails\'] or c[\'notifications\'][\'destination_ids\'],\'Configure approved recipients or destination IDs.\'\n    c[\'scope_signature\']=signature(c);c[\'monitor_id\']=monitor_id(c);c[\'state_table\']=state_table(c)\n    return c\n', 'compiler': '"""Compile a single source contract for one or more environment-bound catalogs."""\nimport json\nfrom pathlib import Path\nfrom configuration import validate,quoted,literal\nHERE=Path(__file__).resolve().parent\n\ndef compile_sources(config,common_source=None,tails=None):\n    c=validate(config)\n    common_source=common_source or (HERE/\'sql/common.sql\').read_text()\n    tails=tails or json.loads((HERE/\'sql/dataset_tails.json\').read_text())\n    result={name:[] for name in tails}\n    empty_fields={\'assignment_id\':\'STRING\',\'source_scope\':\'STRING\',\'source_service_fqn\':\'STRING\',\'asset_fqn\':\'STRING\',\'field_fqn\':\'STRING\',\'term_fqn\':\'STRING\',\'assignment_level\':\'STRING\',\'label_state\':\'STRING\',\'term_is_deleted\':\'BOOLEAN\',\'asset_is_deleted\':\'BOOLEAN\',\'last_seen_at\':\'TIMESTAMP\',\'asset_updated_at_ts\':\'TIMESTAMP\',\'last_run_id\':\'STRING\',\'source_payload_sha256\':\'STRING\'}\n    empty=\'(SELECT \'+\',\'.join(\'CAST(NULL AS \'+v+\') AS \'+k for k,v in empty_fields.items())+\' WHERE false)\'\n    for scope in c[\'scopes\']:\n        replacements={\n            \'{{RAW}}\':scope[\'catalog\'],\'{{SERVICE}}\':(scope.get(\'collate_service\') or \'\').replace("\'","\'\'"),\n            \'{{FRESH_DAYS}}\':str(c[\'collate_freshness_days\']),\n            \'{{EXCLUSIONS}}\':\',\'.join(literal(s) for s in scope[\'excluded_schemas\']),\n            \'{{EXCLUDED_DISPLAY}}\':\', \'.join(scope[\'excluded_schemas\']).replace("\'","\'\'"),\n            \'{{MAPPING_TABLE}}\':quoted(scope[\'mapping_table\']),\n            \'{{COLLATE_SOURCE}}\':quoted(scope[\'collate_assignment_table\']) if scope.get(\'collate_assignment_table\') else empty,\n            \'{{COLLATE_SOURCE_DISPLAY}}\':scope.get(\'collate_assignment_table\') or \'(source not configured)\',\n            \'{{COLLATE_CONFIGURED}}\':\'true\' if scope.get(\'collate_assignment_table\') else \'false\',\n            \'{{TAXONOMY_VALUES}}\':\',\'.join(\'(\'+literal(t[\'classification\'])+\',\'+literal(t[\'pii_class\'])+\',\'+str(t[\'priority\'])+\')\' for t in c[\'taxonomy\']),\n            \'{{SENSITIVITY_TAG}}\':c[\'sensitivity_tag\'].replace("\'","\'\'"),\n            \'{{LEGACY_PII_TAG}}\':c[\'legacy_pii_tag\'].replace("\'","\'\'"),\n            \'{{SOURCE_KEYS}}\':\',\'.join(literal(s) for s in c[\'source_classification_tag_keys\']) or "\'\'",\n            \'{{NATIVE_PREFIX}}\':c[\'native_tag_prefix\'].replace("\'","\'\'"),\n            \'{{LOWEST_PRIORITY}}\':str(max(t[\'priority\'] for t in c[\'taxonomy\']))}\n        for name,tail in tails.items():\n            query=common_source+\'\\n\'+tail+\'\\n\'\n            for a,b in replacements.items():query=query.replace(a,b)\n            assert \'{{\' not in query,\'Unbound source template marker\'\n            # Keep each scoped CTE graph independent before UNION ALL.\n            result[name].append(query)\n    return {name:queries[0] if len(queries)==1 else \'\\nUNION ALL\\n\'.join(\'SELECT * FROM (\\n\'+q+\'\\n)\' for q in queries) for name,queries in result.items()}\n', 'monitor_engine': '"""Stateful metadata monitor. Pure Python: no Databricks calls and no sending."""\nfrom __future__ import annotations\nimport copy,hashlib,json\nfrom datetime import datetime,timedelta,timezone\n\nVERSION=\'classification_monitor_v2\'\nOPEN_STATES={\'OPEN\',\'BACKLOG\',\'GRACE\',\'EVIDENCE_GAP\'}\n\ndef stamp(t):\n    if t.tzinfo is None:t=t.replace(tzinfo=timezone.utc)\n    return t.astimezone(timezone.utc).isoformat()\n\ndef moment(t):\n    if isinstance(t,datetime):return t.replace(tzinfo=timezone.utc) if t.tzinfo is None else t.astimezone(timezone.utc)\n    return datetime.fromisoformat(t.replace(\'Z\',\'+00:00\')).astimezone(timezone.utc)\n\ndef digest(value):return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(\',\',\':\'),default=str).encode()).hexdigest()\ndef asset_key(row):return digest([row[k] for k in (\'catalog_name\',\'schema_name\',\'table_name\',\'column_name\')])\ndef issue_key(asset,finding):return digest([asset,finding])\n\nclass ScopeError(RuntimeError):pass\n\ndef compact(row):\n    keys=(\'catalog_name\',\'schema_name\',\'table_name\',\'column_name\',\'data_type\',\'current_sensitivity\',\n          \'sensitivity_state\',\'actual_priority\',\'expected_priority\',\'expected_sensitivity\',\n          \'remediation_owner\',\'invalid_rule_label_count\',\'name_hint\',\'reconciliation_outcome\')\n    result={k:row.get(k) for k in keys}\n    result[\'column_fqn\']=\'.\'.join(str(result[k]) for k in (\'catalog_name\',\'schema_name\',\'table_name\',\'column_name\'))\n    return result\n\ndef evaluate(rows,previous,now,identity,scope_hash,settings,acknowledgements=()):\n    """Return a complete new snapshot; caller publishes it in one Delta append.\n\n    Existing baseline findings are muted. Acknowledgements mean SQL alert\n    evaluation accepted, not delivery/read confirmation. Unknown visibility\n    and lost mapped evidence never silently resolve an incident.\n    """\n    now=moment(now);now_text=stamp(now)\n    if not rows:raise ScopeError(\'ZERO_VISIBLE_COLUMNS: check scope and metadata permissions\')\n    if len(rows)>settings[\'maximum_columns\']:raise ScopeError(\'COLUMN_BUDGET_EXCEEDED\')\n    observed={asset_key(r):compact(r) for r in rows}\n    if len(observed)!=len(rows):raise ScopeError(\'DUPLICATE_COLUMN_IDENTITIES\')\n    schemas={r[\'catalog_name\']+\'.\'+r[\'schema_name\'] for r in rows}\n    first=previous is None\n    if first:\n        state={\'control\':{\'version\':VERSION,\'identity\':identity,\'scope_hash\':scope_hash,\n                          \'baseline_at\':now_text,\'required_schemas\':sorted(schemas)},\n               \'columns\':{},\'issues\':{},\'pending\':{}}\n    else:\n        state=copy.deepcopy(previous)\n        if state[\'control\'][\'identity\']!=identity:raise ScopeError(\'MONITOR_IDENTITY_CHANGED\')\n        if state[\'control\'][\'scope_hash\']!=scope_hash:raise ScopeError(\'MONITOR_SCOPE_CHANGED: review before creating a new monitor baseline\')\n        missing=set(state[\'control\'][\'required_schemas\'])-schemas\n        if missing:raise ScopeError(\'EXPECTED_SCHEMA_NOT_VISIBLE: \'+\',\'.join(sorted(missing)))\n        prior_count=sum(bool(c.get(\'observed\')) for c in state[\'columns\'].values())\n        if prior_count and len(rows)<prior_count*(1-settings[\'maximum_inventory_drop_fraction\']):\n            raise ScopeError(\'VISIBLE_COLUMN_COUNT_DROPPED: retain previous snapshot and check scope/permissions\')\n    issues=state[\'issues\'];pending=state[\'pending\'];columns=state[\'columns\']\n    # Apply accepted evaluation receipts before deciding reminders/recovery.\n    for ack in acknowledgements:\n        notice=pending.pop(ack[\'notice_id\'],None)\n        if not notice:continue\n        issue=issues.get(notice[\'issue_key\'])\n        if issue and issue[\'generation\']==notice[\'generation\']:\n            issue[\'last_accepted_at\']=ack[\'accepted_at\']\n            if notice[\'kind\']!=\'RECOVERY\':issue[\'ever_announced\']=True\n    # Track first observation and strongest observed valid tier across scans.\n    for key,old in columns.items():old[\'observed\']=False\n    for key,row in observed.items():\n        old=columns.get(key)\n        recognized=row[\'sensitivity_state\']==\'Recognized sensitivity value\'\n        valid_priority=row[\'actual_priority\'] if recognized else None\n        columns[key]=dict(row,first_seen_at=old[\'first_seen_at\'] if old else now_text,\n            origin=old[\'origin\'] if old else (\'BASELINE\' if first else \'NEW\'),\n            baseline_findings=dict((old or {}).get(\'baseline_findings\',{})),\n            baseline_missing=(old or {}).get(\'baseline_missing\',first and row[\'sensitivity_state\']==\'Missing sensitivity tag\'),\n            ever_tagged=bool((old or {}).get(\'ever_tagged\')) or row[\'sensitivity_state\']!=\'Missing sensitivity tag\',\n            protection_floor=min(x for x in [valid_priority,(old or {}).get(\'protection_floor\')] if x is not None)\n                if any(x is not None for x in [valid_priority,(old or {}).get(\'protection_floor\')]) else None,\n            observed=True,last_seen_at=now_text)\n    candidates={}\n    def add(asset,kind,priority,detail,grace=False,required=None,hold=False):\n        row=columns[asset];key=issue_key(asset,kind)\n        candidates[key]={\'issue_key\':key,\'asset_key\':asset,\'finding_type\':kind,\'priority\':priority,\n             \'column_fqn\':row[\'column_fqn\'],\'catalog_name\':row[\'catalog_name\'],\'schema_name\':row[\'schema_name\'],\n             \'table_name\':row[\'table_name\'],\'column_name\':row[\'column_name\'],\n             \'owner\':row.get(\'remediation_owner\') or \'Assign steward\',\'current_sensitivity\':row.get(\'current_sensitivity\'),\n             \'expected_sensitivity\':row.get(\'expected_sensitivity\'),\'required_priority\':required,\n             \'detail\':detail,\'grace\':grace,\'evidence_hold\':hold}\n    for key,row in columns.items():\n        if not row[\'observed\']:\n            add(key,\'COLUMN_NOT_OBSERVED\',\'P2\',\'Column was previously visible; check deletion or reduced metadata visibility. Existing findings remain open.\')\n            for k,old in issues.items():\n                if old[\'asset_key\']==key and old[\'status\'] in OPEN_STATES and old[\'finding_type\']!=\'COLUMN_NOT_OBSERVED\':\n                    add(key,old[\'finding_type\'],old[\'priority\'],\'Column evidence is unavailable; prior incident retained for review.\',required=old.get(\'required_priority\'),hold=True)\n            continue\n        status=row[\'sensitivity_state\'];actual=row[\'actual_priority\'];required=row[\'expected_priority\']\n        if status==\'Missing sensitivity tag\':\n            if row[\'ever_tagged\']:\n                add(key,\'SENSITIVITY_TAG_REMOVED\',\'P1\',\'Previously observed sensitivity tag is absent.\',required=required)\n            elif row[\'origin\']==\'NEW\':\n                add(key,\'NEW_COLUMN_UNTAGGED\',\'P1\' if required is not None else \'P2\',\n                    \'Newly observed column has no sensitivity tag after the classification grace period.\',True,required)\n            elif required is not None:\n                add(key,\'MAPPED_TIER_MISSING\',\'P1\',\'Mapped source evidence requires a sensitivity assignment.\',required=required)\n            # Ordinary baseline missing tags remain aggregate backlog, not incidents.\n        elif status==\'Conflicting sensitivity values\':\n            add(key,\'CONFLICTING_SENSITIVITY_VALUES\',\'P1\',\'Multiple sensitivity values were observed on this column.\')\n        elif status==\'Value outside configured taxonomy\':\n            add(key,\'INVALID_SENSITIVITY_VALUE\',\'P1\',\'Sensitivity value is outside the configured taxonomy.\')\n        elif status==\'Recognized sensitivity value\':\n            if row[\'protection_floor\'] is not None and actual>row[\'protection_floor\']:\n                add(key,\'SENSITIVITY_DOWNGRADED\',\'P1\',\'Assigned tier is weaker than the strongest previously observed valid tier; review the change.\',required=row[\'protection_floor\'])\n            if required is not None and actual>required:\n                add(key,\'MAPPED_TIER_TOO_WEAK\',\'P1\',\'Assigned tier is weaker than the current mapped requirement.\',required=required)\n        if (row.get(\'invalid_rule_label_count\') or 0)>0:\n            add(key,\'SOURCE_MAPPING_INCONSISTENT\',\'P1\',\'Matching source classification rules are inconsistent or conflicting.\')\n        # Loss of a source requirement cannot close an earlier mapped-tier incident.\n        if required is None:\n            for kind in (\'MAPPED_TIER_TOO_WEAK\',\'MAPPED_TIER_MISSING\'):\n                old=issues.get(issue_key(key,kind))\n                if old and old[\'status\'] in OPEN_STATES:\n                    restored=status==\'Recognized sensitivity value\' and actual<=old[\'required_priority\']\n                    if not restored:\n                        add(key,kind,old[\'priority\'],\'Mapped source evidence disappeared; prior requirement retained until evidence or classification is restored.\',required=old[\'required_priority\'],hold=True)\n    # Suppress unchanged initial findings as backlog without creating one incident\n    # per baseline column. Once a suppressed finding clears, recurrence is new.\n    candidates_by_asset={}\n    for candidate in candidates.values():candidates_by_asset.setdefault(candidate[\'asset_key\'],{})[candidate[\'finding_type\']]=candidate\n    for asset,row in columns.items():\n        suppressed=dict(row.get(\'baseline_findings\',{}))\n        present=candidates_by_asset.get(asset,{})\n        for kind in list(suppressed):\n            if kind not in present:suppressed.pop(kind)\n        for kind,candidate in present.items():\n            signature=digest([kind,candidate[\'current_sensitivity\'],candidate[\'required_priority\']])\n            if first:suppressed[kind]=signature\n            if suppressed.get(kind)==signature:candidates.pop(candidate[\'issue_key\'])\n            elif kind in suppressed:suppressed.pop(kind)\n        row[\'baseline_findings\']=suppressed\n    # Retain incident generations so recurrence differs from initial backlog.\n    for key,candidate in candidates.items():\n        old=issues.get(key);new_incident=old is None or old[\'status\']==\'RESOLVED\'\n        if new_incident:\n            issues[key]=dict(candidate,generation=(old[\'generation\']+1 if old else 1),\n                opened_at=now_text,updated_at=now_text,resolved_at=None,\n                baseline_muted=first,ever_announced=False,last_accepted_at=None,notice_sequence=0)\n        else:\n            issues[key].update(candidate,updated_at=now_text)\n        issue=issues[key]\n        # A previously muted baseline missing-tag finding changing to a materially\n        # different finding gets its own key and is therefore eligible to alert.\n        eligible_at=moment(columns[issue[\'asset_key\']][\'first_seen_at\'])+timedelta(minutes=settings[\'classification_grace_minutes\'])\n        if issue[\'evidence_hold\']:issue[\'status\']=\'EVIDENCE_GAP\'\n        elif issue[\'grace\'] and now<eligible_at:issue[\'status\']=\'GRACE\'\n        elif issue[\'baseline_muted\']:issue[\'status\']=\'BACKLOG\'\n        else:issue[\'status\']=\'OPEN\'\n        issue[\'eligible_at\']=stamp(eligible_at) if issue[\'grace\'] else issue[\'opened_at\']\n    for key,issue in issues.items():\n        if key not in candidates and issue[\'status\']!=\'RESOLVED\':\n            issue.update(status=\'RESOLVED\',resolved_at=now_text,updated_at=now_text)\n    # Withdraw undelivered alerts that are already resolved; no false recovery\n    # is sent for an issue that was never announced.\n    for notice_id,notice in list(pending.items()):\n        if notice[\'kind\']==\'SUMMARY\':continue\n        issue=issues.get(notice[\'issue_key\'])\n        if not issue or notice[\'generation\']!=issue[\'generation\']:\n            pending.pop(notice_id);continue\n        if issue[\'status\']==\'RESOLVED\' and notice[\'kind\']!=\'RECOVERY\':pending.pop(notice_id)\n    def enqueue(issue,kind):\n        issue[\'notice_sequence\']+=1\n        notice_id=digest([issue[\'issue_key\'],issue[\'generation\'],kind,issue[\'notice_sequence\']])\n        pending[notice_id]={k:issue.get(k) for k in (\'issue_key\',\'asset_key\',\'generation\',\'finding_type\',\'priority\',\'column_fqn\',\'catalog_name\',\'schema_name\',\'table_name\',\'column_name\',\'owner\',\'current_sensitivity\',\'expected_sensitivity\',\'required_priority\',\'detail\')}\n        pending[notice_id].update(notice_id=notice_id,kind=kind,created_at=now_text)\n        issue[\'last_enqueued_at\']=now_text\n    for issue in issues.values():\n        same_pending=any(n[\'issue_key\']==issue[\'issue_key\'] and n[\'generation\']==issue[\'generation\'] for n in pending.values())\n        if same_pending:continue\n        if issue[\'status\']==\'RESOLVED\':\n            if issue[\'ever_announced\'] and not issue.get(\'recovery_enqueued\'):\n                enqueue(issue,\'RECOVERY\');issue[\'recovery_enqueued\']=True\n        elif issue[\'status\'] in (\'OPEN\',\'EVIDENCE_GAP\') and not issue[\'baseline_muted\']:\n            if not issue[\'ever_announced\']:enqueue(issue,\'NEW\')\n            elif now-moment(issue[\'last_accepted_at\'])>=timedelta(hours=settings[\'reminder_hours\']):enqueue(issue,\'REMINDER\')\n    # A daily environment summary is one digest item, not thousands of incidents.\n    if not first and settings.get(\'daily_summary_enabled\',False) and now.hour>=settings.get(\'daily_summary_hour_utc\',13):\n        day=now.date().isoformat()\n        if state[\'control\'].get(\'last_summary_date\')!=day and not any(n[\'kind\']==\'SUMMARY\' for n in pending.values()):\n            missing=sum(r[\'sensitivity_state\']==\'Missing sensitivity tag\' for r in rows)\n            notice_id=digest([\'summary\',state[\'control\'][\'scope_hash\'],day])\n            pending[notice_id]={\'notice_id\':notice_id,\'issue_key\':\'SUMMARY\',\'asset_key\':\'SUMMARY\',\'generation\':1,\n                \'kind\':\'SUMMARY\',\'finding_type\':\'COVERAGE_SUMMARY\',\'priority\':\'P3\',\'column_fqn\':\'Environment summary\',\n                \'catalog_name\':\'(configured scope)\',\'schema_name\':\'(summary)\',\'table_name\':\'(summary)\',\n                \'column_name\':f\'{missing} of {len(rows)} visible columns missing sensitivity tags\',\n                \'owner\':\'Governance team\',\'created_at\':now_text,\'detail\':\'Coverage backlog is a summary; no baseline per-column incidents were created.\'}\n            state[\'control\'][\'last_summary_date\']=day\n    ordered=sorted(pending.values(),key=lambda n:(n[\'priority\'],n[\'created_at\'],n[\'notice_id\']))\n    selected=[n[\'notice_id\'] for n in ordered[:settings[\'maximum_notifications_per_run\']]]\n    for notice in pending.values():notice[\'selected_for_batch\']=notice[\'notice_id\'] in selected\n    state[\'summary\']={\'observed_columns\':len(rows),\'known_columns\':len(columns),\n        \'missing_tag_columns\':sum(r[\'sensitivity_state\']==\'Missing sensitivity tag\' for r in rows),\n        \'open_incidents\':sum(i[\'status\'] in (\'OPEN\',\'EVIDENCE_GAP\') for i in issues.values()),\n        \'baseline_backlog\':sum(c[\'observed\'] and c.get(\'baseline_missing\',False) and not c[\'ever_tagged\'] and c[\'sensitivity_state\']==\'Missing sensitivity tag\' for c in columns.values()),\n        \'grace_incidents\':sum(i[\'status\']==\'GRACE\' for i in issues.values()),\n        \'new_untagged_open\':sum(i[\'finding_type\']==\'NEW_COLUMN_UNTAGGED\' and i[\'status\']==\'OPEN\' for i in issues.values()),\n        \'pending_notifications\':len(pending),\'selected_notifications\':len(selected),\n        \'baseline_run\':first,\'observed_at\':now_text}\n    return state\n', 'monitor_provision': '"""Native Databricks resource definitions. No API calls on import."""\nimport re\nfrom urllib.parse import urlparse\n\ndef csv_values(value):return sorted(set(x.strip() for x in value.split(\',\') if x.strip()))\ndef validate_inputs(warehouse,cluster,emails,destinations,dashboard_url,workspace_host,poll):\n    assert re.fullmatch(r\'[0-9a-fA-F]{16,}\',warehouse or \'\'),\'Enter the existing SQL warehouse ID.\'\n    assert re.fullmatch(r\'[A-Za-z0-9-]+\',cluster or \'\'),\'Enter an existing approved Spark cluster ID.\'\n    assert len(emails)+len(destinations)<=100,\'At most 100 alert subscribers/destinations.\'\n    assert emails or destinations,\'Enter workspace notification emails or existing notification destination IDs.\'\n    assert all(re.fullmatch(r\'[^\\s<>@]+@[^\\s<>@]+\\.[^\\s<>@]+\',e) for e in emails),\'Use valid workspace notification emails.\'\n    assert all(re.fullmatch(r\'[A-Za-z0-9-]+\',d) for d in destinations),\'Use destination IDs, not webhook URLs.\'\n    assert poll in (15,30,60),\'Supported schedules: 15, 30 or 60 minutes.\'\n    if dashboard_url:\n        p=urlparse(dashboard_url);h=urlparse(workspace_host)\n        assert p.scheme==\'https\' and p.hostname==h.hostname and not p.username and not p.password,\'Dashboard URL must belong to this workspace.\'\n\ndef cron(minutes,offset=2):return f\'0 {offset} * * * ?\' if minutes==60 else f\'0 {offset}/{minutes} * * * ?\'\ndef subscriptions(emails,destinations):\n    return [{\'user_email\':e} for e in emails]+[{\'destination_id\':d} for d in destinations]\n\ndef alert_definition(name,query,warehouse,emails,destinations,body,*,heartbeat=False,poll=60):\n    result={\'display_name\':name,\'query_text\':query,\'warehouse_id\':warehouse,\n      \'evaluation\':{\'source\':{\'name\':\'attention_required\' if heartbeat else \'notice_count\',\'aggregation\':\'MAX\'},\n       \'comparison_operator\':\'GREATER_THAN\',\'threshold\':{\'value\':{\'double_value\':0}},\n       \'empty_result_state\':\'ERROR\',\'notification\':{\'subscriptions\':subscriptions(emails,destinations),\n        \'retrigger_seconds\':86400 if heartbeat else 1,\'notify_on_ok\':heartbeat}},\n      \'schedule\':{\'quartz_cron_schedule\':cron(poll,7 if heartbeat else 2),\'timezone_id\':\'UTC\',\'pause_status\':\'PAUSED\'},\n      \'custom_template_format\':\'MARKDOWN\',\'custom_summary\':name,\n      \'custom_description\':body+\'\\n\\n@QUERY_RESULT_TABLE\\n\\nAlert details: @ALERT_URL\'}\n    if not heartbeat:result[\'parameters\']=[{\'name\':\'monitor_run_id\',\'type\':\'STRING\',\'value\':\'__NO_RUN__\'}]\n    return result\n\ndef job_definition(monitor_id,notebook_path,cluster,warehouse,alert_id,emails,destinations,settings):\n    base={\'scope_signature\':settings[\'scope_signature\'],\'environment_config_json\':settings[\'environment_config_json\']}\n    collect={\'task_key\':\'collect\',\'existing_cluster_id\':cluster,\'max_retries\':1,\'min_retry_interval_millis\':60000,\'timeout_seconds\':1800,\n      \'notebook_task\':{\'notebook_path\':notebook_path,\'source\':\'WORKSPACE\',\'base_parameters\':dict(base,mode=\'collect\',run_token=\'{{job.run_id}}\',installed_job_id=\'{{job.id}}\')}}\n    condition={\'task_key\':\'has_notifications\',\'depends_on\':[{\'task_key\':\'collect\'}],\n      \'condition_task\':{\'left\':\'{{tasks.collect.values.notification_count}}\',\'op\':\'GREATER_THAN\',\'right\':\'0\'}}\n    evaluate={\'task_key\':\'evaluate_alert\',\'depends_on\':[{\'task_key\':\'has_notifications\',\'outcome\':\'true\'}],\n      \'max_retries\':0,\'timeout_seconds\':900,\n      \'alert_task\':{\'alert_id\':alert_id,\'warehouse_id\':warehouse,\n       \'parameters\':{\'monitor_run_id\':\'{{tasks.collect.values.monitor_run_id}}\'}}}\n    ack={\'task_key\':\'record_evaluation\',\'depends_on\':[{\'task_key\':\'evaluate_alert\'}],\n      \'existing_cluster_id\':cluster,\'max_retries\':1,\'min_retry_interval_millis\':60000,\'timeout_seconds\':600,\n      \'notebook_task\':{\'notebook_path\':notebook_path,\'source\':\'WORKSPACE\',\'base_parameters\':dict(base,mode=\'ack\',\n       target_run_id=\'{{tasks.collect.values.monitor_run_id}}\',run_token=\'{{job.run_id}}\',installed_job_id=\'{{job.id}}\')}}\n    return {\'name\':\'Raw Classification Monitor - \'+settings[\'environment\']+\' \'+monitor_id[-8:],\'description\':\'Stateful metadata-only classification monitor; baseline, grace, deduplicated notices, reminders and recovery. Managed by monitor \'+monitor_id,\n      \'tags\':{\'governance_component\':\'classification_monitor\',\'monitor_id\':monitor_id,\'environment\':settings[\'environment\']},\n      \'max_concurrent_runs\':1,\'queue\':{\'enabled\':True},\'timeout_seconds\':3600,\n      \'email_notifications\':{\'on_failure\':emails},\n      \'webhook_notifications\':{\'on_failure\':[{\'id\':d} for d in destinations]},\n      \'schedule\':{\'quartz_cron_schedule\':cron(settings[\'poll_minutes\']),\'timezone_id\':\'UTC\',\'pause_status\':\'PAUSED\'},\n      \'tasks\':[collect,condition,evaluate,ack]}\n', 'monitor_queries': '"""Environment-bound queries generated from the deployment configuration."""\ndef build(table,monitor_id,maximum_age_minutes):\n    schema=\'.\'.join(table.split(\'.\')[:-1])\n    TABLE=table\n    MONITOR_ID=monitor_id\n    DDL=f\'\'\'CREATE SCHEMA IF NOT EXISTS {schema};\n    CREATE TABLE IF NOT EXISTS {TABLE} (\n     monitor_id STRING,run_id STRING,record_id STRING,record_type STRING,\n     observed_at TIMESTAMP,payload_json STRING\n    ) USING DELTA TBLPROPERTIES (\'ifbi.component\'=\'classification_monitor_v2\');\'\'\'\n    \n    BASE=f\'\'\'WITH published AS (\n     SELECT run_id,observed_at,payload_json,\n     row_number() OVER (ORDER BY observed_at DESC,run_id DESC) AS rn\n     FROM {TABLE} WHERE monitor_id=\'{MONITOR_ID}\' AND record_type=\'RUN\'\n    ), latest AS (SELECT * FROM published WHERE rn=1),\n    acks AS (\n     SELECT get_json_object(payload_json,\'$.notice_id\') AS notice_id,max(observed_at) AS evaluation_accepted_at\n     FROM {TABLE} WHERE monitor_id=\'{MONITOR_ID}\' AND record_type=\'ACK\'\n     GROUP BY get_json_object(payload_json,\'$.notice_id\')\n    )\n    \'\'\'\n    \n    def alert_query():\n        return f"""WITH binding AS (\n SELECT CASE WHEN EXISTS (SELECT 1 FROM {TABLE} WHERE monitor_id=\'{MONITOR_ID}\' AND record_type=\'RUN\' AND run_id=:monitor_run_id)\n THEN 0 ELSE raise_error(\'Monitor run parameter is not bound to a published batch\') END AS binding_error\n), selected AS (\n SELECT get_json_object(payload_json,\'$.notice_id\') AS notice_id,\n get_json_object(payload_json,\'$.kind\') AS event_kind,\n get_json_object(payload_json,\'$.finding_type\') AS finding_type,\n get_json_object(payload_json,\'$.priority\') AS priority,\n get_json_object(payload_json,\'$.catalog_name\') AS catalog_name,\n get_json_object(payload_json,\'$.schema_name\') AS schema_name,\n get_json_object(payload_json,\'$.table_name\') AS table_name,\n get_json_object(payload_json,\'$.column_name\') AS column_name,\n get_json_object(payload_json,\'$.owner\') AS responsible_owner\n FROM {TABLE} j\n WHERE monitor_id=\'{MONITOR_ID}\' AND run_id=:monitor_run_id\n AND record_type=\'NOTICE\' AND get_json_object(payload_json,\'$.selected_for_batch\')=\'true\'\n AND NOT EXISTS (SELECT 1 FROM {TABLE} a WHERE a.monitor_id=j.monitor_id AND a.record_type=\'ACK\'\n AND get_json_object(a.payload_json,\'$.notice_id\')=j.record_id)\n), totals AS (SELECT count(*) AS notice_count FROM selected), grouped AS (\n SELECT event_kind,finding_type,priority,catalog_name,schema_name,table_name,responsible_owner,\n count(*) AS affected_events,\n concat_ws(\'; \',slice(sort_array(collect_set(column_name)),1,5)) AS example_columns\n FROM selected GROUP BY event_kind,finding_type,priority,catalog_name,schema_name,table_name,responsible_owner\n ORDER BY priority,affected_events DESC LIMIT 99\n)\nSELECT t.notice_count+b.binding_error AS notice_count,g.* FROM totals t CROSS JOIN binding b LEFT JOIN grouped g ON true\nORDER BY g.priority,g.affected_events DESC"""\n\n    HEALTH=BASE+f\'\'\'SELECT\n     CASE WHEN l.run_id IS NULL THEN 1\n     WHEN l.observed_at<current_timestamp()-INTERVAL {{MAX_AGE}} MINUTES THEN 1\n     WHEN (SELECT max(observed_at) FROM {TABLE} WHERE monitor_id=\'{MONITOR_ID}\' AND record_type=\'FAILURE\')>l.observed_at THEN 1\n     ELSE 0 END AS attention_required,\n     CASE WHEN l.run_id IS NULL THEN \'Initialize the monitor baseline\'\n     WHEN l.observed_at<current_timestamp()-INTERVAL {{MAX_AGE}} MINUTES THEN \'Scheduled classification check overdue\'\n     WHEN (SELECT max(observed_at) FROM {TABLE} WHERE monitor_id=\'{MONITOR_ID}\' AND record_type=\'FAILURE\')>l.observed_at THEN \'Latest monitor attempt failed\'\n     ELSE \'Monitor current\' END AS monitor_status,\n     l.observed_at AS last_success_at,\n     (SELECT max(observed_at) FROM {TABLE} WHERE monitor_id=\'{MONITOR_ID}\' AND record_type=\'FAILURE\') AS last_failure_at,\n     cast(get_json_object(l.payload_json,\'$.summary.observed_columns\') AS BIGINT) AS last_visible_columns,\n     cast(get_json_object(l.payload_json,\'$.summary.missing_tag_columns\') AS BIGINT) AS missing_tag_columns,\n     cast(get_json_object(l.payload_json,\'$.summary.baseline_backlog\') AS BIGINT) AS baseline_backlog,\n     cast(get_json_object(l.payload_json,\'$.summary.grace_incidents\') AS BIGINT) AS grace_incidents,\n     cast(get_json_object(l.payload_json,\'$.summary.open_incidents\') AS BIGINT) AS open_incidents,\n     cast(get_json_object(l.payload_json,\'$.summary.pending_notifications\') AS BIGINT) AS pending_notifications,\n     current_timestamp() AS refreshed_at\n    FROM (SELECT 1 AS anchor) x LEFT JOIN latest l ON true\'\'\'\n    \n    INCIDENTS=BASE+f\'\'\'SELECT\n     get_json_object(j.payload_json,\'$.issue_key\') AS issue_key,\n     get_json_object(j.payload_json,\'$.finding_type\') AS finding_type,\n     get_json_object(j.payload_json,\'$.status\') AS incident_status,\n     get_json_object(j.payload_json,\'$.priority\') AS priority,\n     get_json_object(j.payload_json,\'$.schema_name\') AS schema_name,\n     get_json_object(j.payload_json,\'$.table_name\') AS table_name,\n     get_json_object(j.payload_json,\'$.column_name\') AS column_name,\n     get_json_object(j.payload_json,\'$.owner\') AS responsible_owner,\n     get_json_object(j.payload_json,\'$.current_sensitivity\') AS current_sensitivity,\n     get_json_object(j.payload_json,\'$.expected_sensitivity\') AS expected_sensitivity,\n     cast(get_json_object(j.payload_json,\'$.generation\') AS INT) AS incident_generation,\n     cast(get_json_object(j.payload_json,\'$.opened_at\') AS TIMESTAMP) AS opened_at,\n     cast(get_json_object(j.payload_json,\'$.eligible_at\') AS TIMESTAMP) AS alert_eligible_at,\n     cast(get_json_object(j.payload_json,\'$.last_accepted_at\') AS TIMESTAMP) AS last_evaluation_accepted_at,\n     cast(get_json_object(j.payload_json,\'$.resolved_at\') AS TIMESTAMP) AS resolved_at,\n     get_json_object(j.payload_json,\'$.detail\') AS action_context\n    FROM {TABLE} j JOIN latest l ON j.run_id=l.run_id\n    WHERE j.monitor_id=\'{MONITOR_ID}\' AND j.record_type=\'ISSUE\'\n    ORDER BY priority,incident_status,opened_at\'\'\'\n    \n    NOTICES=BASE+f\'\'\', last_notice AS (\n     SELECT *,row_number() OVER (PARTITION BY record_id ORDER BY observed_at DESC,run_id DESC) AS notice_rank\n     FROM {TABLE} WHERE monitor_id=\'{MONITOR_ID}\' AND record_type=\'NOTICE\'\n    )\n    SELECT n.record_id AS notice_id,\n     get_json_object(n.payload_json,\'$.issue_key\') AS issue_key,\n     get_json_object(n.payload_json,\'$.kind\') AS event_kind,\n     get_json_object(n.payload_json,\'$.finding_type\') AS finding_type,\n     get_json_object(n.payload_json,\'$.priority\') AS priority,\n     get_json_object(n.payload_json,\'$.column_fqn\') AS column_fqn,\n     get_json_object(n.payload_json,\'$.owner\') AS responsible_owner,\n     cast(get_json_object(n.payload_json,\'$.created_at\') AS TIMESTAMP) AS created_at,\n     CASE WHEN a.notice_id IS NOT NULL THEN \'Alert evaluation accepted\'\n     WHEN p.record_id IS NOT NULL THEN \'Pending alert evaluation\'\n     ELSE \'Withdrawn before evaluation or older incident\' END AS notification_status,\n     a.evaluation_accepted_at\n    FROM last_notice n LEFT JOIN acks a ON n.record_id=a.notice_id\n    LEFT JOIN (SELECT j.record_id FROM {TABLE} j JOIN latest l ON j.run_id=l.run_id\n     WHERE j.monitor_id=\'{MONITOR_ID}\' AND j.record_type=\'NOTICE\') p ON n.record_id=p.record_id\n    WHERE n.notice_rank=1 ORDER BY created_at DESC,notice_id\'\'\'\n    \n    TRENDS=BASE+\'\'\'SELECT observed_date,visible_columns,missing_tags,baseline_backlog,new_untagged_open,open_incidents FROM (\n     SELECT cast(observed_at AS DATE) AS observed_date,\n     cast(get_json_object(payload_json,\'$.summary.observed_columns\') AS BIGINT) AS visible_columns,\n     cast(get_json_object(payload_json,\'$.summary.missing_tag_columns\') AS BIGINT) AS missing_tags,\n     cast(get_json_object(payload_json,\'$.summary.baseline_backlog\') AS BIGINT) AS baseline_backlog,\n     cast(get_json_object(payload_json,\'$.summary.new_untagged_open\') AS BIGINT) AS new_untagged_open,\n     cast(get_json_object(payload_json,\'$.summary.open_incidents\') AS BIGINT) AS open_incidents,\n     row_number() OVER (PARTITION BY cast(observed_at AS DATE) ORDER BY observed_at DESC,run_id DESC) AS daily_rank\n     FROM published\n    ) WHERE daily_rank=1 ORDER BY observed_date\'\'\'\n    return {\'ddl\':DDL,\'alert\':alert_query(),\'health\':HEALTH.replace(\'{MAX_AGE}\',str(maximum_age_minutes)),\'incidents\':INCIDENTS,\'notices\':NOTICES,\'trends\':TRENDS}\n'}
COMMON_SOURCE = "-- Metadata only. Scope, service identity and freshness target are set in config.json.\nWITH\nsettings AS (\n SELECT '{{RAW}}' AS raw_catalog, '{{SERVICE}}' AS collate_service,\n        {{FRESH_DAYS}} AS freshness_days\n),\ntaxonomy AS (\n SELECT * FROM VALUES {{TAXONOMY_VALUES}}\n AS expected_taxonomy(classification,pii_class,priority)\n),\ninventory AS (\n SELECT c.table_catalog AS catalog_name,c.table_schema AS schema_name,\n c.table_name,c.column_name,c.data_type,c.ordinal_position,\n concat(c.table_catalog,'.',c.table_schema,'.',c.table_name) AS table_fqn,\n concat(c.table_catalog,'.',c.table_schema,'.',c.table_name,'.',c.column_name) AS column_fqn,\n coalesce(t.table_type,'Metadata object') AS object_type,\n coalesce(t.table_owner,'Assign steward') AS remediation_owner,\n CASE WHEN c.table_schema='collate' THEN 'Collate integration metadata'\n ELSE 'Raw catalog objects' END AS scope_category,\n CASE WHEN c.comment IS NULL OR trim(c.comment)='' THEN 'Description missing'\n ELSE 'Description present' END AS description_state\n FROM system.information_schema.columns c\n LEFT JOIN system.information_schema.tables t\n ON c.table_catalog=t.table_catalog AND c.table_schema=t.table_schema AND c.table_name=t.table_name\n WHERE c.table_catalog='{{RAW}}'\n AND c.table_schema NOT IN ({{EXCLUSIONS}})\n),\ntags AS (\n SELECT DISTINCT t.catalog_name,t.schema_name,t.table_name,t.column_name,t.tag_name,t.tag_value\n FROM system.information_schema.column_tags t\n JOIN inventory c ON t.catalog_name=c.catalog_name AND t.schema_name=c.schema_name\n AND t.table_name=c.table_name AND t.column_name=c.column_name\n WHERE t.catalog_name='{{RAW}}'\n),\nmapping_raw AS (\n SELECT source_tag_name,source_tag_value,collate_fqn,ifbi_classification,pii_class,tier_priority\n FROM {{MAPPING_TABLE}}\n),\nsource_key_health AS (\n SELECT source_tag_name,source_tag_value,\n count(DISTINCT concat(coalesce(ifbi_classification,'<NULL>'),'|',coalesce(pii_class,'<NULL>'),'|',coalesce(cast(tier_priority AS STRING),'<NULL>'))) AS target_variants,\n count(*) AS key_rows\n FROM mapping_raw GROUP BY source_tag_name,source_tag_value\n),\nmapping_checked AS (\n SELECT m.*,k.target_variants,k.key_rows,\n CASE WHEN m.source_tag_name IS NULL OR trim(m.source_tag_name)='' THEN 'Source tag name missing'\n WHEN x.classification IS NULL THEN 'Classification outside configured taxonomy'\n WHEN m.pii_class IS NULL OR m.tier_priority IS NULL OR m.pii_class<>x.pii_class OR m.tier_priority<>x.priority THEN 'Tier, pii_class or priority disagree'\n WHEN m.source_tag_value IS NULL AND m.source_tag_name NOT LIKE '{{NATIVE_PREFIX}}%' THEN 'NULL match value requires explicit matching rule'\n WHEN k.target_variants>1 THEN 'Same source tag maps to conflicting targets'\n ELSE 'Rule usable' END AS rule_state\n FROM mapping_raw m\n JOIN source_key_health k ON m.source_tag_name <=> k.source_tag_name AND m.source_tag_value <=> k.source_tag_value\n LEFT JOIN taxonomy x ON m.ifbi_classification=x.classification\n),\nsource_tags AS (\n SELECT t.* FROM tags t\n WHERE t.tag_name<>'{{SENSITIVITY_TAG}}'\n AND (t.tag_name IN ({{SOURCE_KEYS}}) OR t.tag_name LIKE '{{NATIVE_PREFIX}}%'\n OR t.tag_name IN (SELECT source_tag_name FROM mapping_raw))\n),\nsource_matches AS (\n SELECT t.*,m.ifbi_classification,m.pii_class,m.tier_priority,m.rule_state\n FROM source_tags t LEFT JOIN mapping_checked m\n ON t.tag_name=m.source_tag_name\n AND (t.tag_value=m.source_tag_value OR (m.source_tag_value IS NULL AND m.source_tag_name LIKE '{{NATIVE_PREFIX}}%'))\n),\nsource_rollup AS (\n SELECT catalog_name,schema_name,table_name,column_name,\n count(DISTINCT concat(tag_name,'=',coalesce(tag_value,'<NULL>'))) AS source_label_count,\n count(DISTINCT CASE WHEN rule_state='Rule usable' THEN concat(tag_name,'=',coalesce(tag_value,'<NULL>')) END) AS mapped_source_label_count,\n count(DISTINCT CASE WHEN rule_state IS NULL THEN concat(tag_name,'=',coalesce(tag_value,'<NULL>')) END) AS unmapped_source_label_count,\n count(DISTINCT CASE WHEN rule_state IS NOT NULL AND rule_state<>'Rule usable' THEN concat(tag_name,'=',coalesce(tag_value,'<NULL>')) END) AS invalid_rule_label_count,\n min(CASE WHEN rule_state='Rule usable' THEN tier_priority END) AS uc_expected_priority,\n concat_ws('; ',sort_array(collect_set(concat(tag_name,'=',coalesce(tag_value,'<NULL>'))))) AS source_labels,\n concat_ws('; ',sort_array(collect_set(CASE WHEN rule_state IS NULL THEN concat(tag_name,'=',coalesce(tag_value,'<NULL>')) END))) AS unmapped_source_labels\n FROM source_matches GROUP BY catalog_name,schema_name,table_name,column_name\n),\ntag_rollup AS (\n SELECT t.catalog_name,t.schema_name,t.table_name,t.column_name,\n count(*) AS tag_assignment_count,\n count(DISTINCT CASE WHEN t.tag_name='{{SENSITIVITY_TAG}}' THEN t.tag_value END) AS sensitivity_value_count,\n count_if(t.tag_name='{{SENSITIVITY_TAG}}') AS sensitivity_assignment_count,\n min(CASE WHEN t.tag_name='{{SENSITIVITY_TAG}}' THEN t.tag_value END) AS single_tier_value,\n min(CASE WHEN t.tag_name='{{SENSITIVITY_TAG}}' THEN x.priority END) AS actual_priority,\n concat_ws('; ',sort_array(collect_set(CASE WHEN t.tag_name='{{SENSITIVITY_TAG}}' THEN t.tag_value END))) AS sensitivity_values,\n concat_ws('; ',sort_array(collect_set(CASE WHEN t.tag_name='auto_class' THEN t.tag_value END))) AS auto_class_values,\n concat_ws('; ',sort_array(collect_set(CASE WHEN t.tag_name='{{LEGACY_PII_TAG}}' THEN t.tag_value END))) AS legacy_pii_values,\n count(DISTINCT CASE WHEN t.tag_name='{{LEGACY_PII_TAG}}' THEN t.tag_value END) AS legacy_pii_value_count,\n min(CASE WHEN t.tag_name='{{LEGACY_PII_TAG}}' THEN t.tag_value END) AS single_legacy_pii,\n concat_ws('; ',sort_array(collect_set(CASE WHEN t.tag_name LIKE '{{NATIVE_PREFIX}}%' THEN t.tag_name END))) AS native_class_tags,\n concat_ws('; ',sort_array(collect_set(concat(t.tag_name,'=',coalesce(t.tag_value,'<NULL>'))))) AS all_tag_evidence\n FROM tags t LEFT JOIN taxonomy x ON t.tag_name='{{SENSITIVITY_TAG}}' AND t.tag_value=x.classification\n GROUP BY t.catalog_name,t.schema_name,t.table_name,t.column_name\n),\nglossary_ranked AS (\n SELECT a.*,row_number() OVER (\n PARTITION BY source_scope,source_service_fqn,assignment_id\n ORDER BY last_seen_at DESC NULLS LAST,asset_updated_at_ts DESC NULLS LAST,\n last_run_id DESC NULLS LAST,source_payload_sha256 DESC NULLS LAST) AS record_rank\n FROM {{COLLATE_SOURCE}} a\n),\nglossary_latest AS (\n SELECT * FROM glossary_ranked\n WHERE record_rank=1 OR assignment_id IS NULL OR trim(assignment_id)=''\n),\nglossary_raw AS (\n SELECT a.*,\n CASE WHEN startswith(a.field_fqn,concat(s.collate_service,'.{{RAW}}.'))\n THEN substring(a.field_fqn,length(s.collate_service)+2)\n WHEN a.source_service_fqn=s.collate_service AND startswith(a.field_fqn,'{{RAW}}.') THEN a.field_fqn\n ELSE NULL END AS uc_column_fqn,\n CASE WHEN a.assignment_id IS NULL OR trim(a.assignment_id)='' THEN 'Assignment identity missing'\n WHEN a.source_service_fqn IS NOT NULL AND a.source_service_fqn<>s.collate_service THEN 'Different Collate service'\n WHEN a.term_is_deleted=true OR a.asset_is_deleted=true THEN 'Deleted term or asset'\n WHEN a.term_is_deleted IS NULL OR a.asset_is_deleted IS NULL THEN 'Deletion state missing'\n WHEN a.assignment_level IS NULL OR a.assignment_level<>'column' THEN 'Assignment is not column-level'\n WHEN a.label_state IS NULL OR a.label_state<>'Confirmed' THEN 'Steward confirmation required'\n WHEN a.last_seen_at IS NULL THEN 'Observation timestamp missing'\n WHEN a.last_seen_at>current_timestamp()+INTERVAL 5 MINUTES THEN 'Observation timestamp is in the future'\n WHEN a.last_seen_at<current_timestamp()-INTERVAL {{FRESH_DAYS}} DAYS THEN 'Refresh Collate snapshot'\n ELSE 'Current confirmed assignment' END AS assignment_state\n FROM glossary_latest a CROSS JOIN settings s\n WHERE instr(lower(coalesce(a.field_fqn,'')),'.{{RAW}}.')>0\n OR startswith(lower(coalesce(a.field_fqn,'')),'{{RAW}}.')\n OR instr(lower(coalesce(a.asset_fqn,'')),'.{{RAW}}.')>0\n OR startswith(lower(coalesce(a.asset_fqn,'')),'{{RAW}}.')\n),\nterm_targets AS (\n SELECT collate_fqn,\n count(DISTINCT CASE WHEN rule_state='Rule usable' THEN ifbi_classification END) AS valid_target_count,\n min(CASE WHEN rule_state='Rule usable' THEN tier_priority END) AS term_priority,\n count_if(rule_state<>'Rule usable') AS unusable_rules\n FROM mapping_checked WHERE collate_fqn IS NOT NULL GROUP BY collate_fqn\n),\ncollate_rows AS (\n SELECT a.assignment_id,a.source_scope,a.source_service_fqn,a.asset_fqn,a.field_fqn,\n a.term_fqn,a.assignment_level,a.label_state,a.last_seen_at,a.assignment_state,\n a.uc_column_fqn,c.catalog_name,c.schema_name,c.table_name,c.column_name,\n m.term_priority,\n CASE WHEN a.assignment_state<>'Current confirmed assignment' THEN a.assignment_state\n WHEN a.uc_column_fqn IS NULL THEN 'Column identity format needs mapping'\n WHEN c.column_name IS NULL THEN 'Column absent from visible Raw inventory'\n WHEN m.collate_fqn IS NULL THEN 'Glossary term has no sensitivity rule'\n WHEN m.valid_target_count<>1 OR m.unusable_rules>0 THEN 'Glossary term mapping needs correction'\n ELSE 'Current mapped column assignment' END AS reconciliation_state\n FROM glossary_raw a\n LEFT JOIN inventory c ON a.uc_column_fqn=c.column_fqn\n LEFT JOIN term_targets m ON a.term_fqn=m.collate_fqn\n),\ncollate_rollup AS (\n SELECT catalog_name,schema_name,table_name,column_name,\n count(*) AS collate_assignment_rows,\n count_if(reconciliation_state='Current mapped column assignment') AS usable_collate_assignments,\n min(CASE WHEN reconciliation_state='Current mapped column assignment' THEN term_priority END) AS collate_expected_priority,\n concat_ws('; ',sort_array(collect_set(term_fqn))) AS collate_terms,\n concat_ws('; ',sort_array(collect_set(reconciliation_state))) AS collate_details,\n max(last_seen_at) AS collate_last_seen_at\n FROM collate_rows WHERE column_name IS NOT NULL\n GROUP BY catalog_name,schema_name,table_name,column_name\n),\ncollate_feed AS (\n SELECT (SELECT count(*) FROM glossary_latest) AS glossary_feed_rows,\n (SELECT count(*) FROM glossary_raw) AS raw_candidate_rows,\n (SELECT coalesce(count_if(reconciliation_state='Current mapped column assignment'),0) FROM collate_rows) AS usable_raw_assignments,\n (SELECT max(last_seen_at) FROM glossary_latest) AS latest_feed_observation,\n (SELECT max(last_seen_at) FROM glossary_raw) AS latest_raw_observation,\n CASE WHEN {{COLLATE_CONFIGURED}}=false THEN 'Collate assignment source not configured'\n WHEN (SELECT count(*) FROM glossary_latest)=0 THEN 'Glossary feed contains no records'\n WHEN (SELECT count(*) FROM glossary_raw)=0 THEN 'No Raw assignments found in glossary feed'\n WHEN (SELECT coalesce(count_if(reconciliation_state='Current mapped column assignment'),0) FROM collate_rows)=0 THEN 'Raw glossary assignments need attention'\n ELSE 'Mapped Raw glossary evidence available' END AS feed_outcome\n),\nassembled AS (\n SELECT c.*,coalesce(t.tag_assignment_count,0) AS tag_assignment_count,\n coalesce(t.sensitivity_assignment_count,0) AS sensitivity_assignment_count,\n coalesce(t.sensitivity_value_count,0) AS sensitivity_value_count,\n CASE WHEN coalesce(t.sensitivity_assignment_count,0)=0 THEN 'Missing sensitivity tag'\n WHEN t.sensitivity_value_count>1 THEN 'Conflicting sensitivity values'\n WHEN t.actual_priority IS NULL THEN 'Value outside configured taxonomy'\n ELSE 'Recognized sensitivity value' END AS sensitivity_state,\n CASE WHEN coalesce(t.sensitivity_assignment_count,0)=0 THEN '(missing)'\n ELSE coalesce(t.sensitivity_values,'(empty value)') END AS current_sensitivity,\n t.actual_priority,coalesce(t.auto_class_values,'') AS auto_class_values,\n coalesce(t.native_class_tags,'') AS native_class_tags,\n coalesce(t.legacy_pii_values,'') AS legacy_pii_values,\n coalesce(t.all_tag_evidence,'') AS all_tag_evidence,\n CASE WHEN coalesce(t.legacy_pii_value_count,0)=0 THEN 'No legacy pii_class tag'\n WHEN t.legacy_pii_value_count>1 THEN 'Conflicting legacy pii_class values'\n WHEN x.pii_class IS NULL THEN 'Resolve sensitivity tier before legacy comparison'\n WHEN t.single_legacy_pii=x.pii_class THEN 'Legacy value agrees'\n ELSE 'Legacy pii_class disagrees' END AS legacy_alignment,\n coalesce(u.source_label_count,0) AS source_label_count,\n coalesce(u.mapped_source_label_count,0) AS mapped_source_label_count,\n coalesce(u.unmapped_source_label_count,0) AS unmapped_source_label_count,\n coalesce(u.invalid_rule_label_count,0) AS invalid_rule_label_count,\n coalesce(u.source_labels,'') AS source_labels,\n coalesce(u.unmapped_source_labels,'') AS unmapped_source_labels,\n u.uc_expected_priority,g.collate_expected_priority,\n coalesce(g.collate_assignment_rows,0) AS collate_assignment_rows,\n coalesce(g.usable_collate_assignments,0) AS usable_collate_assignments,\n coalesce(g.collate_terms,'') AS collate_terms,\n coalesce(g.collate_details,f.feed_outcome) AS collate_details,\n g.collate_last_seen_at,\n CASE WHEN u.uc_expected_priority IS NOT NULL AND g.collate_expected_priority IS NOT NULL THEN 'UC source tags + Collate glossary'\n WHEN u.uc_expected_priority IS NOT NULL THEN 'UC source tags'\n WHEN g.collate_expected_priority IS NOT NULL THEN 'Collate mapped glossary'\n ELSE 'No usable source mapping' END AS reconciliation_basis,\n CASE WHEN u.uc_expected_priority IS NULL THEN g.collate_expected_priority\n WHEN g.collate_expected_priority IS NULL THEN u.uc_expected_priority\n ELSE least(u.uc_expected_priority,g.collate_expected_priority) END AS expected_priority,\n CASE WHEN regexp_like(lower(c.column_name),'(^|_)(ssn|soc_sec|social_security_number|socialsecuritynumber)($|_)') THEN 'SSN name hint'\n WHEN regexp_like(lower(c.column_name),'(^|_)(email|e_mail|email_address)($|_)') THEN 'Email name hint'\n WHEN regexp_like(lower(c.column_name),'(^|_)(dob|birth_date|date_of_birth)($|_)') THEN 'Birth date name hint'\n WHEN regexp_like(lower(c.column_name),'(^|_)(phone|phone_number|telephone|mobile_number)($|_)') THEN 'Phone name hint'\n WHEN regexp_like(lower(c.column_name),'(^|_)(bank_account|bank_account_number|credit_card|credit_card_number|iban|routing_number)($|_)') THEN 'Payment identifier name hint'\n WHEN regexp_like(lower(c.column_name),'(^|_)(claim_notes|medical_notes|diagnosis|health_data)($|_)') THEN 'Sensitive free-text or health name hint'\n ELSE 'No configured name hint' END AS name_hint\n FROM inventory c\n LEFT JOIN tag_rollup t USING(catalog_name,schema_name,table_name,column_name)\n LEFT JOIN source_rollup u USING(catalog_name,schema_name,table_name,column_name)\n LEFT JOIN collate_rollup g USING(catalog_name,schema_name,table_name,column_name)\n LEFT JOIN taxonomy x ON t.sensitivity_value_count=1 AND t.single_tier_value=x.classification\n CROSS JOIN collate_feed f\n),\nclassified AS (\n SELECT a.*,coalesce(x.classification,'(no mapped requirement)') AS expected_sensitivity,\n CASE WHEN sensitivity_state<>'Recognized sensitivity value' THEN sensitivity_state\n WHEN invalid_rule_label_count>0 THEN 'Source mapping rule needs correction'\n WHEN expected_priority IS NULL AND unmapped_source_label_count>0 THEN 'Source labels need mapping rules'\n WHEN expected_priority IS NULL THEN 'Sensitivity assigned; source mapping absent'\n WHEN actual_priority>expected_priority THEN 'Assigned tier below mapped requirement'\n WHEN actual_priority<expected_priority THEN 'Assigned tier above mapped requirement'\n WHEN unmapped_source_label_count>0 THEN 'Mapped tier agrees; additional labels need rules'\n ELSE 'Assigned tier agrees with mapped evidence' END AS reconciliation_outcome,\n CASE WHEN uc_expected_priority IS NOT NULL AND collate_expected_priority IS NOT NULL\n AND uc_expected_priority<>collate_expected_priority THEN 'UC and Collate mapped priorities differ'\n WHEN uc_expected_priority IS NOT NULL AND collate_expected_priority IS NOT NULL THEN 'UC and Collate mapped priorities agree'\n WHEN collate_assignment_rows>0 AND usable_collate_assignments=0 THEN 'Collate assignment needs attention'\n WHEN usable_collate_assignments>0 THEN 'Collate mapped requirement available'\n ELSE collate_details END AS collate_alignment\n FROM assembled a LEFT JOIN taxonomy x ON a.expected_priority=x.priority\n),\nscored AS (\n SELECT a.*,\n CASE WHEN sensitivity_state IN ('Conflicting sensitivity values','Value outside configured taxonomy') THEN 'P1 - Correct configuration'\n WHEN invalid_rule_label_count>0 THEN 'P1 - Correct configuration'\n WHEN expected_priority IS NOT NULL AND (sensitivity_state='Missing sensitivity tag' OR actual_priority>expected_priority) THEN 'P1 - Correct configuration'\n WHEN legacy_alignment IN ('Legacy pii_class disagrees','Conflicting legacy pii_class values') THEN 'P2 - Steward review'\n WHEN collate_alignment='UC and Collate mapped priorities differ' THEN 'P2 - Steward review'\n WHEN unmapped_source_label_count>0 THEN 'P2 - Steward review'\n WHEN name_hint<>'No configured name hint' AND (sensitivity_state='Missing sensitivity tag' OR actual_priority={{LOWEST_PRIORITY}}) THEN 'P2 - Steward review'\n WHEN collate_assignment_rows>0 AND usable_collate_assignments=0 THEN 'P2 - Steward review'\n WHEN sensitivity_state='Missing sensitivity tag' THEN 'P3 - Complete classification'\n WHEN expected_priority IS NOT NULL AND actual_priority<expected_priority THEN 'P2 - Steward review'\n WHEN expected_priority IS NULL THEN 'P3 - Add source evidence'\n ELSE 'P4 - Maintain' END AS action_priority\n FROM classified a\n),\ncolumn_results AS (\n SELECT a.*,\n CASE WHEN sensitivity_state='Conflicting sensitivity values' THEN 'Resolve multiple sensitivity values against the approved classification'\n WHEN sensitivity_state='Value outside configured taxonomy' THEN 'Correct the sensitivity value or update the approved taxonomy'\n WHEN invalid_rule_label_count>0 THEN 'Correct conflicting or inconsistent source mapping rules before changing tags'\n WHEN expected_priority IS NOT NULL AND sensitivity_state='Missing sensitivity tag' THEN concat('Review source evidence and assign ',expected_sensitivity)\n WHEN expected_priority IS NOT NULL AND actual_priority>expected_priority THEN concat('Review possible under-classification; mapped requirement is ',expected_sensitivity)\n WHEN legacy_alignment IN ('Legacy pii_class disagrees','Conflicting legacy pii_class values') THEN 'Resolve legacy pii_class and sensitivity-tier disagreement'\n WHEN collate_alignment='UC and Collate mapped priorities differ' THEN 'Steward to reconcile UC and Collate source classification priorities'\n WHEN unmapped_source_label_count>0 THEN 'Review unmapped source labels; add approved exact-key/value rules'\n WHEN sensitivity_state='Missing sensitivity tag' AND name_hint<>'No configured name hint' THEN 'Inspect column context for the name hint and assign a reviewed classification'\n WHEN actual_priority={{LOWEST_PRIORITY}} AND name_hint<>'No configured name hint' THEN 'Review the sensitive-name hint against the lowest configured tier; confirm intended classification'\n WHEN collate_assignment_rows>0 AND usable_collate_assignments=0 THEN 'Refresh or correct the Collate assignment evidence'\n WHEN sensitivity_state='Missing sensitivity tag' THEN 'Assign a steward-reviewed sensitivity classification'\n WHEN expected_priority IS NOT NULL AND actual_priority<expected_priority THEN 'Review stronger assigned tier; preserve it until any reduction is approved'\n WHEN expected_priority IS NULL THEN 'Capture classification rationale or connect the approved source assignment'\n ELSE 'Retain classification and review when schema or source evidence changes' END AS recommended_action,\n CASE WHEN expected_priority IS NOT NULL AND sensitivity_state='Recognized sensitivity value'\n THEN true ELSE false END AS comparable_column,\n CASE WHEN name_hint<>'No configured name hint' AND (sensitivity_state='Missing sensitivity tag' OR actual_priority={{LOWEST_PRIORITY}})\n THEN true ELSE false END AS name_hint_review,\n current_timestamp() AS refreshed_at,\n current_user() AS metadata_reader\n FROM scored a\n)\n"
DATASET_TAILS = {'column_inventory': 'SELECT * FROM column_results ORDER BY action_priority,coalesce(expected_priority,5),schema_name,table_name,ordinal_position', 'tag_dictionary': "SELECT '{{RAW}}' AS catalog_name,t.tag_name,t.tag_value,count(*) AS column_assignments,\n count(DISTINCT concat(t.catalog_name,'.',t.schema_name,'.',t.table_name)) AS table_count,\n count(DISTINCT t.schema_name) AS schema_count,\n CASE WHEN t.tag_name='{{SENSITIVITY_TAG}}' THEN 'Assigned sensitivity tier'\n WHEN t.tag_name='{{LEGACY_PII_TAG}}' THEN 'Legacy treatment tag'\n WHEN t.tag_name='auto_class' THEN 'auto_class source label'\n WHEN t.tag_name LIKE '{{NATIVE_PREFIX}}%' THEN 'Native classification tag'\n WHEN t.tag_name IN (SELECT source_tag_name FROM mapping_raw) THEN 'Mapped source tag key'\n ELSE 'Other tag' END AS evidence_kind\nFROM tags t GROUP BY t.tag_name,t.tag_value\nORDER BY column_assignments DESC,t.tag_name,t.tag_value", 'mapping_rule_health': "SELECT '{{RAW}}' AS catalog_name,m.source_tag_name,m.source_tag_value,m.collate_fqn,m.ifbi_classification,\n m.pii_class,m.tier_priority,m.rule_state,m.target_variants,m.key_rows,\n count(DISTINCT c.column_fqn) AS matching_visible_columns\nFROM mapping_checked m LEFT JOIN tags t\n ON t.tag_name=m.source_tag_name AND (t.tag_value=m.source_tag_value OR (m.source_tag_value IS NULL AND m.source_tag_name LIKE '{{NATIVE_PREFIX}}%'))\nLEFT JOIN inventory c ON t.catalog_name=c.catalog_name AND t.schema_name=c.schema_name\n AND t.table_name=c.table_name AND t.column_name=c.column_name\nGROUP BY m.source_tag_name,m.source_tag_value,m.collate_fqn,m.ifbi_classification,\n m.pii_class,m.tier_priority,m.rule_state,m.target_variants,m.key_rows\nORDER BY m.tier_priority,m.source_tag_name,m.source_tag_value", 'unmapped_source_labels': "SELECT '{{RAW}}' AS catalog_name,tag_name,tag_value,\n count(DISTINCT concat(catalog_name,'.',schema_name,'.',table_name,'.',column_name)) AS affected_columns,\n concat_ws('; ',sort_array(collect_set(schema_name))) AS affected_schemas,\n 'Review source provenance and add an approved exact-key/value mapping; do not infer tag aliases' AS recommended_action\nFROM source_matches WHERE rule_state IS NULL GROUP BY tag_name,tag_value\nORDER BY affected_columns DESC,tag_name,tag_value", 'collate_feed_health': "SELECT '{{RAW}}' AS catalog_name,f.*,current_timestamp() AS refreshed_at,\n '{{COLLATE_SOURCE_DISPLAY}}' AS source_table,\n '{{SERVICE}}' AS expected_service,\n {{FRESH_DAYS}} AS freshness_target_days,\n (SELECT count(*) FROM glossary_ranked) AS source_rows_before_dedup,\n (SELECT count(*) FROM glossary_latest WHERE assignment_id IS NULL OR trim(assignment_id)='') AS missing_assignment_ids,\n (SELECT count(DISTINCT field_fqn) FROM glossary_raw) AS raw_candidate_columns,\n (SELECT count(*) FROM collate_rows WHERE column_name IS NOT NULL) AS identity_matched_rows,\n (SELECT count(*) FROM collate_rows WHERE assignment_state='Refresh Collate snapshot') AS older_raw_assignments,\n (SELECT count(*) FROM collate_rows WHERE reconciliation_state='Glossary term has no sensitivity rule') AS unmapped_glossary_rows,\n CASE WHEN f.raw_candidate_rows=0 THEN 'Connect the Raw classification assignment feed; this glossary feed currently has no Raw candidates'\n WHEN f.usable_raw_assignments=0 THEN 'Use the assignment exceptions table to resolve identity, confirmation, freshness or mapping issues'\n ELSE 'Review per-column comparisons and resolve any differences' END AS recommended_action\nFROM collate_feed f", 'collate_assignment_trace': "SELECT assignment_id,source_scope,source_service_fqn,asset_fqn,field_fqn,uc_column_fqn,\n coalesce(catalog_name,'{{RAW}}') AS catalog_name,schema_name,table_name,column_name,term_fqn,assignment_level,label_state,\n assignment_state,reconciliation_state,term_priority,last_seen_at,\n current_timestamp() AS refreshed_at\nFROM collate_rows ORDER BY reconciliation_state,field_fqn,term_fqn", 'scope_and_refresh': "SELECT c.schema_name,c.scope_category,c.object_type,c.remediation_owner,\n count(DISTINCT c.table_fqn) AS table_or_view_count,count(*) AS visible_columns,\n current_user() AS metadata_reader,current_timestamp() AS refreshed_at,\n '{{RAW}}' AS catalog_name,\n '{{EXCLUDED_DISPLAY}}' AS excluded_schemas\nFROM column_results c\nGROUP BY c.schema_name,c.scope_category,c.object_type,c.remediation_owner\nORDER BY visible_columns DESC", 'actionable_inventory': "SELECT * FROM column_results WHERE action_priority IN ('P1 - Correct configuration','P2 - Steward review') ORDER BY action_priority,coalesce(expected_priority,999),schema_name,table_name,ordinal_position"}
